style.css:
@-moz-document domain("roblox.com") {
/* ---------- COLOUR SYSTEM ---------- */

  :root {
    --pink: #ff6fae;
    --hot-pink: #ff3f91;
    --soft-pink: #ffb6d5;
    --pale-pink: #ffd9e9;

    --black: #080609;
    --black2: #100b10;
    --black3: #171017;

    --gray: #242024;
    --border: #492638;

    --white: #fff7fb;
    --muted: #c9a9b8;
  }


  /* ---------- WHOLE ROBLOX BACKGROUND ---------- */

  html,
  body,
  .dark-theme,
  #rbx-body {
    background:
      radial-gradient(circle at 15% 20%,
        rgba(255,105,170,.12),
        transparent 25%),
      radial-gradient(circle at 85% 70%,
        rgba(255,60,145,.09),
        transparent 25%),
      #080609 !important;

    color: var(--white) !important;
  }


  /* ---------- TOP NAVIGATION ---------- */

  .dark-theme .rbx-header,
  .rbx-header {
    background:
      linear-gradient(
        90deg,
        rgba(255,70,145,.12),
        rgba(0,0,0,.92) 35%,
        rgba(255,100,175,.10)
      ) !important;

    border-bottom: 1px solid #5b2943 !important;

    box-shadow:
      0 0 18px rgba(255,70,145,.12),
      0 3px 25px rgba(0,0,0,.8) !important;

    backdrop-filter: blur(12px);
  }


  /* ---------- NAV TEXT ---------- */

  .rbx-header a,
  .rbx-header .text-header,
  .rbx-header span {
    color: var(--white) !important;
  }

  .rbx-header a:hover,
  .rbx-header .text-header:hover {
    color: var(--soft-pink) !important;
    text-shadow: 0 0 10px rgba(255,100,175,.7);
  }


  /* ---------- SEARCH BAR ---------- */

  .rbx-header .navbar-search,
  #navbar-universal-search,
  #navbar-search-input,
  .navbar-search .input-field {

    background: rgba(255,255,255,.045) !important;

    border: 1px solid #613047 !important;

    border-radius: 14px !important;

    color: white !important;

    box-shadow:
      inset 0 0 12px rgba(255,70,145,.05),
      0 0 12px rgba(255,70,145,.06) !important;
  }

  #navbar-search-input::placeholder,
  .navbar-search input::placeholder {
    color: #b998a8 !important;
  }


  /* ---------- LEFT SIDEBAR ---------- */

  .dark-theme .rbx-left-col,
  .rbx-left-col {

    background:
      linear-gradient(
        180deg,
        rgba(255,80,150,.07),
        rgba(0,0,0,.35)
      ) !important;

    border-right: 1px solid #3e2431 !important;

    box-shadow:
      8px 0 25px rgba(0,0,0,.35) !important;
  }


  .rbx-left-col a,
  .rbx-left-col .font-header-2 {

    color: #ead5df !important;

    transition:
      .18s ease !important;
  }


  .rbx-left-col a:hover,
  .rbx-left-col li:hover {

    color: #fff !important;

    background:
      linear-gradient(
        90deg,
        rgba(255,70,145,.22),
        transparent
      ) !important;

    border-radius: 10px !important;

    text-shadow:
      0 0 10px rgba(255,90,160,.7);
  }


  /* ---------- GENERAL CARDS ---------- */

  .dark-theme .card,
  .dark-theme .section,
  .dark-theme .game-card,
  .dark-theme .game-card-container,
  .card,
  .section {

    background:
      linear-gradient(
        145deg,
        rgba(255,255,255,.045),
        rgba(255,80,150,.025)
      ) !important;

    border:
      1px solid #432432 !important;

    border-radius:
      16px !important;

    box-shadow:
      0 8px 30px rgba(0,0,0,.35),
      inset 0 0 20px rgba(255,70,145,.025) !important;
  }


  /* ---------- GAME CARDS ---------- */

  .game-card:hover,
  .game-card-container:hover {

    border-color:
      #a94c75 !important;

    box-shadow:
      0 0 20px rgba(255,70,145,.16),
      0 10px 35px rgba(0,0,0,.55) !important;

    transform:
      translateY(-2px);

    transition:
      .2s ease !important;
  }


  .game-card-name,
  .game-name-title {

    color:
      #fff2f7 !important;
  }


  .game-card-info {

    color:
      #caa8b8 !important;
  }


  /* ---------- BUTTONS ---------- */

  button,
  .btn-primary,
  .btn-secondary,
  .btn-common,
  .btn-control {

    background:
      linear-gradient(
        135deg,
        #ff4b9a,
        #d93678
      ) !important;

    color:
      white !important;

    border:
      1px solid #ff86bb !important;

    border-radius:
      12px !important;

    box-shadow:
      0 0 14px rgba(255,65,145,.18) !important;

    transition:
      .18s ease !important;
  }


  button:hover,
  .btn-primary:hover,
  .btn-secondary:hover {

    background:
      linear-gradient(
        135deg,
        #ff78b4,
        #ed3f87
      ) !important;

    box-shadow:
      0 0 22px rgba(255,75,155,.4) !important;

    transform:
      translateY(-1px);
  }


  /* ---------- INPUTS ---------- */

  input,
  textarea,
  select {

    background:
      #120c11 !important;

    color:
      #fff !important;

    border:
      1px solid #593047 !important;

    border-radius:
      11px !important;
  }


  input:focus,
  textarea:focus,
  select:focus {

    border-color:
      #ff5da4 !important;

    box-shadow:
      0 0 12px rgba(255,75,150,.2) !important;

    outline:
      none !important;
  }


  /* ---------- LINKS ---------- */

  a {

    color:
      #ff8bbb !important;
  }

  a:hover {

    color:
      #ffc1dc !important;

    text-shadow:
      0 0 9px rgba(255,100,175,.7);
  }


  /* ---------- HEADINGS ---------- */

  h1,
  h2,
  h3,
  h4,
  h5,
  h6 {

    color:
      #fff5f9 !important;

    text-shadow:
      0 0 12px rgba(255,80,155,.12);
  }


  /* ---------- PROFILE ---------- */

  .profile-header,
  .profile-container {

    background:
      linear-gradient(
        135deg,
        rgba(255,70,145,.08),
        rgba(0,0,0,.35)
      ) !important;

    border:
      1px solid #492638 !important;

    border-radius:
      18px !important;
  }


  /* ---------- DROPDOWNS / POPUPS ---------- */

  .dropdown-menu,
  .popover,
  .modal-content,
  .modal-dialog {

    background:
      #100a0f !important;

    color:
      white !important;

    border:
      1px solid #5b2943 !important;

    border-radius:
      15px !important;

    box-shadow:
      0 15px 50px rgba(0,0,0,.75),
      0 0 25px rgba(255,60,140,.08) !important;
  }


  /* ---------- SELECTED TABS ---------- */

  .selected,
  .active,
  .tab-active {

    background:
      rgba(255,70,145,.16) !important;

    color:
      #ffacd0 !important;

    border-radius:
      10px !important;
  }


  /* =====================================================
     ⭐ PINK FLASH / STAR DETAILS
     ===================================================== */

  .rbx-header::after {

    content:
      "✦  ✧  ★  ✧  ✦";

    position:
      absolute;

    right:
      25px;

    top:
      8px;

    color:
      rgba(255,185,215,.8);

    font-size:
      13px;

    letter-spacing:
      7px;

    text-shadow:
      0 0 10px #ff78b5,
      0 0 20px rgba(255,100,175,.55);

    pointer-events:
      none;
  }


  /* =====================================================
     ? RETRO CAMERA / FLASH FEEL
     ===================================================== */

  body::before {

    content:
      "✦";

    position:
      fixed;

    left:
      4%;

    top:
      17%;

    font-size:
      70px;

    color:
      rgba(255,210,230,.08);

    text-shadow:
      0 0 30px rgba(255,100,175,.45);

    pointer-events:
      none;

    z-index:
      0;
  }


  body::after {

    content:
      "✧       ★          ✦             ✧";

    position:
      fixed;

    right:
      3%;

    bottom:
      8%;

    color:
      rgba(255,150,195,.10);

    font-size:
      25px;

    letter-spacing:
      12px;

    pointer-events:
      none;

    z-index:
      0;
  }


  /* =====================================================
     ? BLACK / PINK CHECKER ACCENT
     ===================================================== */

  .rbx-left-col::after {

    content:
      "";

    position:
      absolute;

    bottom:
      0;

    left:
      0;

    width:
      100%;

    height:
      8px;

    background:
      repeating-conic-gradient(
        #ff78b4 0 25%,
        #120b10 0 50%
      )
      0 / 16px 16px;

    opacity:
      .7;
  }


  /* =====================================================
     ? SOFT PINK GLOW AROUND IMPORTANT UI
     ===================================================== */

  .avatar-card,
  .avatar-container,
  .thumbnail-2d-container {

    border-radius:
      14px !important;
  }


  .avatar-card:hover,
  .thumbnail-2d-container:hover {

    box-shadow:
      0 0 18px rgba(255,80,155,.2) !important;
  }


  /* =====================================================
     ? CHERRY / RED-PINK ACCENT
     ===================================================== */

  .icon-robux,
  .icon-nav-robux,
  [class*="robux"] {

    filter:
      saturate(1.2) !important;
  }


  /* =====================================================
     SCROLLBAR
     ===================================================== */

  ::-webkit-scrollbar {

    width:
      9px;

    background:
      #09070a;
  }

  ::-webkit-scrollbar-thumb {

    background:
      linear-gradient(
        #ff78b5,
        #b92f67
      );

    border-radius:
      10px;

    border:
      2px solid #09070a;
  }

  ::-webkit-scrollbar-thumb:hover {

    background:
      #ff9bc7;
  }


  /* =====================================================
     ✨ SUBTLE GRAIN / DREAMY OVERLAY
     ===================================================== */

  #rbx-body::after {

    content:
      "";

    position:
      fixed;

    inset:
      0;

    pointer-events:
      none;

    z-index:
      9999;

    background:
      radial-gradient(
        circle at center,
        transparent 40%,
        rgba(0,0,0,.25)
      );

    mix-blend-mode:
      multiply;
  }
}
